%%| fig-cap: "Структура паттерна Proxy: Proxy и Service разделяют один интерфейс"
%%| fig-width: 7
%%| fig-height: 4
classDiagram
    class ServiceInterface {
        <<interface>>
        +operation()
    }
    class Service {
        +operation()
    }
    class Proxy {
        -realService: Service
        +Proxy(s: Service)
        +checkAccess(): bool
